package com.portfolio.employee;
import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@RestController @RequestMapping("/api/employees") public class EmployeeController {private final EmployeeRepository repo;public EmployeeController(EmployeeRepository repo){this.repo=repo;}@GetMapping public List<Employee> all(){return repo.findAll();}@GetMapping("/{id}") public Employee get(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Employee create(@RequestBody Employee e){if(e.getName()==null||e.getName().isBlank()||e.getEmail()==null||e.getEmail().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST);return repo.save(e);}@PutMapping("/{id}") public Employee update(@PathVariable Long id,@RequestBody Employee input){Employee e=get(id);e.setName(input.getName());e.setDepartment(input.getDepartment());e.setEmail(input.getEmail());return repo.save(e);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);repo.deleteById(id);}}